using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using System.Security.Claims;using RoomReservation.Infrastructure.Persistence;
namespace RoomReservation.Api.Controllers;
[ApiController,Authorize(Roles="OrgAdmin,SuperAdmin"),Route("api/v1/rooms/{roomId:guid}/sharing")]
public class RoomSharingController(AppDbContext db):ControllerBase{
 Guid Org=>Guid.Parse(User.FindFirstValue("organization_id")!);
 [HttpGet]public async Task<IActionResult> List(Guid roomId){if(!await db.Rooms.AnyAsync(x=>x.Id==roomId&&x.OrganizationId==Org))return NotFound();return Ok(await db.RoomAccesses.Where(x=>x.RoomId==roomId&&x.OwnerOrganizationId==Org&&x.OrganizationId!=Org).Join(db.Organizations,o=>o.OrganizationId,i=>i.Id,(a,o)=>new{a.Id,organizationId=a.OrganizationId,organizationName=o.Name,a.CanView,a.CanBook,a.RequiresApproval}).ToListAsync());}
 [HttpPost]public async Task<IActionResult> Share(Guid roomId,ShareInput input){if(input.OrganizationId==Org)return BadRequest("Cannot share to the owning organization");if(!await db.Rooms.AnyAsync(x=>x.Id==roomId&&x.OrganizationId==Org))return NotFound();if(!await db.Organizations.AnyAsync(x=>x.Id==input.OrganizationId))return BadRequest("Organization not found");var access=await db.RoomAccesses.FirstOrDefaultAsync(x=>x.RoomId==roomId&&x.OrganizationId==input.OrganizationId);if(access is not null&&access.OwnerOrganizationId!=Org)return Conflict("Room access is owned by another organization");if(access is null){access=new(){RoomId=roomId,OrganizationId=input.OrganizationId,OwnerOrganizationId=Org};db.RoomAccesses.Add(access);}access.CanView=input.CanView;access.CanBook=input.CanBook;access.RequiresApproval=input.RequiresApproval;await db.SaveChangesAsync();return Ok(access);}
 [HttpDelete("{organizationId:guid}")]public async Task<IActionResult> Remove(Guid roomId,Guid organizationId){var access=await db.RoomAccesses.FirstOrDefaultAsync(x=>x.RoomId==roomId&&x.OrganizationId==organizationId&&x.OwnerOrganizationId==Org);if(access is null)return NotFound();db.RoomAccesses.Remove(access);await db.SaveChangesAsync();return NoContent();}
 public record ShareInput(Guid OrganizationId,bool CanView=true,bool CanBook=false,bool RequiresApproval=true);
}
